quests[12420] = { id = 12420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[12421] = { id = 12421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Gemeinsam ist man stark, {name}. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in der Dunkeldornenlodge im Tal der Geister in Orgrimmar.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in der Dunkeldornenlodge im Tal der Geister in Orgrimmar.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Euer Papierkram sieht in Ordnung aus. Willkommen im Verein, {name}!\n\nStellt Euch schon mal darauf ein, zu Beginn jedes Monats Post von uns zu erhalten. Schaut doch mal vorbei, wenn Euch gefällt, was Ihr bekommen habt, und wir werden Euch noch mehr davon verkaufen. Dieser Verein gibt und gibt und gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12479] = { id = 12479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf nach Nordend!", description = "Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra Bericht erstattet oder nach Valgarde im Heulenden Fjord geht.", sourceObjective = "Sprecht mit dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra oder im Hafen der Vergeltung im Heulenden Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12480] = { id = 12480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf nach Nordend!", description = "Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Horde in der Kriegshymnenfeste in der Boreanischen Tundra Bericht erstattet oder zum Hafen der Vergeltung im Heulenden Fjord geht.", sourceObjective = "Sprecht mit dem Rekrutierer der Horde im Inneren der Kriegshymnenfeste in der Boreanischen Tundra oder im Hafen der Vergeltung im Heulenden Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12491] = { id = 12491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbräus Düsterbräu", description = "Coren Düsterbräus Leiche hielt dieses fest an seinen Bauch gedrückte Fass umklammert. Hierbei muss es sich um sein berüchtigtes Düsterbräu handeln!", sourceObjective = "Bringt Düsterbräus Düsterbräu zu Ipfelkofer Eisenfass im Braufestlager in der Nähe von Eisenschmiede.", progress = "{name}, Ihr macht so ein grimmiges Gesicht. Habt Ihr schlechte Neuigkeiten?", completion = "Das ist Coren Düsterbräus Trunk? Das Bier, das er um jeden Preis beim Braufest präsentieren wollte? Nun, rein offiziell können wir diesen Beitrag zwar nicht anerkennen, doch aus Respekt einem gescheiterten Braumeister gegenüber, werde ich mir vielleicht ein Schlückchen erlauben...", sourceObjectiveStatus = "unverified-source-field" }
quests[12492] = { id = 12492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbräus Düsterbräu", description = "Coren Düsterbräus Leiche hielt dieses fest an seinen Bauch gedrückte Fass umklammert. Hierbei muss es sich um sein berüchtigtes Düsterbräu handeln!", sourceObjective = "Bringt Düsterbräus Düsterbräu zu Zapfus Schwindelfass im Braufestlager in der Nähe von Orgrimmar.", progress = "He, {name}, Euer Gesicht ist so dreckig! Seid Ihr in die Schwarzfelstiefen hinabgestiegen?", completion = "Ah, Düsterbräu hat also sein Bier letztendlich beim Braufest präsentieren können. Wie schade nur, dass er dafür hat sterben müssen...\n\nNaja... zum Wohl, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12513] = { id = 12513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netter Hut...", description = "Mein Hut? Ja, er sieht von weitem etwas ungewöhnlich aus, ich weiß... nur wenige Schneider wissen, wie man sie anfertigt.\n\nAls ich noch jung und heißblütig war, galt er als eine Art Siegestrophäe. Viele kamen und wollten ihn mir streitig machen... doch niemand schaffte es.\n\nAch ja, lange ist's nun her. Doch heute bin ich ein alter Mann: Ich trinke, ich gehe fischen, doch ich duelliere mich nicht mehr.", sourceObjective = "Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris.", progress = "Ich war unschlagbar, zu jener Zeit... stolz und das zurecht. Noch nie hat ein Herausforderer diesen großartigen Hut gewonnen... noch nie...", completion = "Mein... mein Hut! IHR wart das also. Hab' ich's mir doch gedacht. Die alten Narben fingen wieder an wehzutun, als Ihr näherkamt - doch... so jung?! Ihr habt Euch kein Bisschen verändert!\n\nNun... jetzt wisst Ihr also mein Geheimnis. Ich WURDE besiegt... ein einziges Mal. Ihr habt ihn mehr als nur verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12515] = { id = 12515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netter Hut...", description = "Mein Hut? Ja, er sieht von weitem etwas ungewöhnlich aus, ich weiß... nur wenige Schneider wissen, wie man sie anfertigt.\n\nAls ich noch jung und heißblütig war, galt er als eine Art Siegestrophäe. Viele kamen und wollten ihn mir streitig machen... doch niemand schaffte es.\n\nAch ja, lange ist's nun her. Doch heute bin ich ein alter Mann: Ich trinke, ich gehe fischen, doch ich duelliere mich nicht mehr.", sourceObjective = "Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris.", progress = "Ich war unschlagbar, zu jener Zeit... stolz und das zurecht. Noch nie hat ein Herausforderer diesen großartigen Hut gewonnen... noch nie...", completion = "Mein... mein Hut! IHR wart das also. Hab' ich's mir doch gedacht. Die alten Narben fingen wieder an wehzutun, als Ihr näherkamt - doch... so jung?! Ihr habt Euch kein Bisschen verändert!\n\nNun... jetzt wisst Ihr also mein Geheimnis. Ich WURDE besiegt... ein einziges Mal. Ihr habt ihn mehr als nur verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12616] = { id = 12616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kammer der Geheimnisse", description = "Ausgezeichnet, ein erfahrener Abenteurer. Genau das, was wir brauchen.\n\nEs gab Gerede unter den Kirin Tor, die Medivhs Turm bewachen, dass etwas in Karazhan nicht stimme. Es ging darum, dass dort drinnen eine neue Macht schlummere, eine Macht, die weder der Magie des Wächters noch der Legion unterstellt sei. Ihren Erkundungen zufolge scheint es, als handle es sich um einen Elfenprinzen namens Tenris Mirkblut; außerdem gäbe es Grund zur Annahme, dass er der Geißel diene.\n\nGeht, mein Freund, untersucht Mirkbluts Kammer und bringt sämtliche Informationen mit, die Ihr finden könnt.", sourceObjective = "Der Abgesandte der Argentumdämmerung möchte, dass Ihr Tenris Mirkbluts Kammer in den Bedienstetenunterkünften in Karazhan durchsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12911] = { id = 12911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Credit Test" }
quests[13408] = { id = 13408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13409] = { id = 13409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13410] = { id = 13410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13411] = { id = 13411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13429] = { id = 13429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ablenkungsmanöver für Akama", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", sourceObjective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", completion = "<Xi'ri pulsiert vor Energie, Ihr fühlt, wie ein Gegenstand in Euren Händen Gestalt annimmt. Es ist das Medaillon, das Ihr A'dal im Namen von Akama gegeben habt. Seine Macht hat sich durch die Magie der Naaru noch verstärkt. Die Sha'tar haben Euch das Medaillon von Karabor anvertraut, und damit den Zugang zum Schwarzen Tempel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13430] = { id = 13430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Magtheridon", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", completion = "Ihr habt Euch als Wesen mit großer Macht bewiesen. Die Naaru sind sich einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[13431] = { id = 13431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Knüppel von Kar'desh", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!", sourceObjective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", progress = "Mit dem Knüppel werde ich meine Fesseln lösen können und zum Schlangenschrein zurückkehren, um meine Rache an Vashj und ihren Dienern zu üben!", completion = "Endlich!\n\nMit gelösten Fesseln und dem Knüppel in meinem Besitz werde ich diese Meereshexe wieder zurück in die eisigen Tiefen senden...", sourceObjectiveStatus = "unverified-source-field" }
quests[14352] = { id = 14352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Mylady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf Weiteres abseits der Hügel der Klingenhauer aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", sourceObjective = "Bringt die kleine Rolle zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14353] = { id = 14353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Angeblich hält sich dieser Malcin außerhalb der Hügel der Klingenhauer auf. Keine Frage - er muss sterben.\n\nMeine Kontakte in Orgrimmar erzählen mir, dass ihre Späher dort unten Anzeichen der Seuche gefunden haben. Die Stacheleber weisen auch Anzeichen einer Verseuchung auf und sie sind um einiges stärker. Was auch immer die Geißel dort unten unternimmt, muss ein Ende haben. Jetzt sofort.\n\nFindet diesen Malcin und schaltet ihn aus. Meldet Euch wieder bei mir, sobald er tot ist.", sourceObjective = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14355] = { id = 14355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Scharlachrote Kloster", description = "Eine meiner Aufgaben, während ich hier stationiert bin, ist es, den Verlassenen dabei zu helfen, ihre Grenzen zu überwachen – und das ist exakt das, was Ihr, {class}, für mich erledigen werdet.\n\nIch mag am Leben sein, doch ist der Scharlachrote Kreuzzug bereit, meine Leute genauso schnell niederzumähen wie einen der Untoten. Sie sind ein Problem hier, ein großes sogar, und Ihr werdet etwas dagegen unternehmen.\n\nGeht zum Kloster und erschlagt Hochinquisitorin Weißsträhne und ihre Offiziere.", sourceObjective = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Bragor Blutfaust in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14356] = { id = 14356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Zugehört, {class}.\n\nIhr mögt vielleicht nichts davon wissen, aber Orgrimmar hat ein Problem. Tief im Flammenschlund treibt eine Sekte des Schattenrats, die sich 'Die Sengende Klinge' nennt, ihr Unwesen. Es sind hauptsächlich Orcs und ich kann vertrauliche Informationen nicht in die Hände der Grunzer dort legen. Hier kommt Ihr ins Spiel.\n\nSie sollten zwei Bücher in ihrem Besitz haben. Ich möchte sie weder der Sengenden Klinge noch den Verlassenen überlassen. Bringt sie direkt zu mir.", sourceObjective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt, und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Die Klinge wird sich an Euch binden. Wenn das passiert, tragt sie zu Caladis Prunkspeer in Qel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist Euch beim Sonnenbrunnen widerfahren?", completion = "Das ist unglaublich, {name}! Ihr habt es tatsächlich geschafft! Alle Quel'dorei kennen die Geschichte von Thalorien Morgensucher und Quel'Delar, aber keiner hätte je geglaubt, dass das Schwert wiederhergestellt werden würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist beim Sonnenbrunnen geschehen?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Morgensuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan muss sterben!", description = "Anub'Rekhan, einst mächtiger Spinnenfürst im Nerubischen Reich, ist in die Fänge des Lichkönigs geraten, der ihn zu einem Untoten machte.\n\nJetzt fristet er sein Dasein als Gruftlord in seinem Domizil im Arachnidenviertel von Naxxramas und ersinnt Strategien für Kel'Thuzad.\n\nDer Rat der Sechs hat verfügt, dass Anub'Rekhan sterben muss!", sourceObjective = "Tötet Anub'Rhekan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth der Seuchenfürst muss sterben!", description = "Noth der Seuchenfürst, Verräter und Feigling! In der Anzahl gegeißelter Seelen folgt er gleich hinter dem Lichkönig selbst.\n\nBegebt Euch schleunigst nach Naxxramas. Dort hält er sich im Seuchenviertel hinter seiner untoten Dienerschaft versteckt.\n\nVernichtet ihn! Der Rat der Sechs hat verfügt, dass Noth sterben muss!", sourceObjective = "Tötet Noth den Seuchenfürst.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Eine Sorge weniger... Jetzt, wo Noth tot ist, wird auch die Forschung der Geißel nach verbesserten Methoden zur Erschaffung Untoter ein Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrukteur Razuvious muss sterben!", description = "Instrukteur Razuvious stolziert selbstgefällig durch das Militärviertel von Naxxramas. Man sagt, nur ein von ihm persönlich ausgebildeter Todesritter könne der Macht seiner Klinge standhalten.\n\nIhr und Eure Gruppe sollt das Gegenteil beweisen.\n\nDer Rat der Sechs hat verfügt, dass Razuvious sterben muss!", sourceObjective = "Tötet Instrukteur Razuvious.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Gut gemacht, {class}! Razuvious' Untergang hatte eine Verwirrung des Militärbefehls der Geißel aus Naxxramas zur Folge.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickwerk muss sterben!", description = "Der sogenannte \"Abgesandte des Krieges\", Flickwerk, ist die ultimative Monstrosität. Außerdem setzt er unseren Truppen in der Drachenöde schwer zu.\n\nIch möchte, dass Ihr Eure Gefährten versammelt und Euch in das Konstruktviertel von Naxxramas begebt, wo Ihr dieses Konstrukt auseinandernehmen sollt.\n\nDer Rat der Sechs hat verfügt, dass Flickwerk sterben muss!", sourceObjective = "Tötet Flickwerk.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Kinder überall auf der Welt werden besser schlafen können, jetzt, da Flickwerk nicht mehr lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Sobald die Klinge wiederhergestellt ist, zeigt sie Caladis Prunkspeer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24797] = { id = 24797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[63448] = { id = 63448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Deluxelieferung", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63450] = { id = 63450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Deluxelieferung", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[63767] = { id = 63767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtel in der Kugel", sourceObjective = "Grüße, {class}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63768] = { id = 63768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtel in der Kugel", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[63865] = { id = 63865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank", sourceObjective = "Grüße, {name},\n\nHier ist ein besonderes Geschenk für Euch als passionierten Sammler! Wir möchten Euch diesen kleinen aber aufgeweckten Freund überreichen. Möge er Euch zu neuen Abenteuern auf der anderen Seite des Dunklen Portals in der Scherbenwelt führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63866] = { id = 63866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beherrschung des Lichts", description = "Nehmt dieses Gefäß, {name}. Seine Magie wird es Euch erlauben, die Macht dieser Kreatur an Euch zu nehmen. Mit ihr werdet Ihr in der Lage sein, Euren gefallenen Kameraden wieder zum Leben zu erwecken.\n\nManche werden sagen, dass unser Handeln falsch ist, aber vieles von dem, was uns widerfahren ist, ist auch falsch. Sollen wir denn solch ein Geschenk wegwerfen?\n\nSie behalten ihre Kritik für sich, wenn unsere Macht die weitere Zerstörung Silbermonds verhindert. Doch sobald sie sich in teuer erkaufter Sicherheit ihren magischen Süchten hingeben können, erheben sie ihre Einsprüche.", sourceObjective = "Füllt das schimmernde Gefäß bei M'uru und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück.", progress = "Habt Ihr schon mit Magister Astalor Blutschwur gesprochen?", completion = "Gut gemacht, {name}. Die vom Licht gewährten Kräfte sind niemals auf 'natürlichem' Wege zu den Blutrittern gekommen, aber wir sind nicht so willensschwach, um unseren Weg von der Natur diktieren zu lassen.\n\nUnsere Beherrschung des Arkanen hat uns einen Pfad durch diese rauen Zeiten eröffnet. Die Kräfte fließen nicht mehr frei in diesen Hallen, doch sie sind da, für die hartnäckigen und willensstarken. Nur wenige sind heutzutage mutig genug, oder verfügen über die Begabung, sie zu meistern, aber ich weiß, dass Ihr den Orden nicht enttäuschen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64028] = { id = 64028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Sturmwind, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64031] = { id = 64031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64034] = { id = 64034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber diese eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64035] = { id = 64035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "<Jeder/Jede:c> {class} verwendet andere Fähigkeiten und Talente. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!" }
quests[64037] = { id = 64037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Auf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Lord Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung benötigt Eure Hilfe dabei, die Östlichen Pestländer von der Geißel zu befreien.\n\nUm in die Östlichen Pestländer zu gelangen, sprecht mit dem Greifenmeister Dungar Trinkfest. Seine Greifen können Euch schneller als jedes Pferd dorthin bringen.\n\nFür Ruhm und Ehre der Allianz!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64038] = { id = 64038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAuf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend in den Verwüsteten Landen zu melden. Sprecht mit Dungar Trinkfest, um einen Flug dorthin zu arrangieren.\n\nSobald Ihr angekommen seid, meldet Euch umgehend bei Wachkommandant Reldorn Netherschwund. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Wachkommandant Reldorn Netherschwund in den Verwüsteten Landen ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64046] = { id = 64046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Orgrimmar, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64047] = { id = 64047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Donnerfels, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung?", sourceObjectiveStatus = "unverified-source-field" }
quests[64048] = { id = 64048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64049] = { id = 64049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
