quests[64053] = { id = 64053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "<Jeder/Jede:c> {class} verwendet andere Fähigkeiten und Talente. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid fast bereit für den Kampf, {name}!" }
quests[64063] = { id = 64063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAlle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich in den Verwüsteten Landen zu melden. Begebt Euch zum Zeppelinmeister vor den Toren Orgrimmars und fliegt zum Basislager Grom'gol. Sprecht dort mit Thysta, um einen Flug nach Steinard zu erhalten.\n\nMeldet Euch umgehend bei Kriegsherr Dar'toon. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Kriegsherr Dar'toon ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64064] = { id = 64064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Alle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich bei Leonidas Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung hat ihre Position in den Pestländern gefestigt und benötigt Eure Hilfe, um ihre Siege zu konsolidieren.\n\nBesucht Zeppelinmeister Frezza vor dem Haupttor und reist zur Unterstadt. Reist von dort aus zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nDas Schicksal wartet!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er erwartet Eure Ankunft in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64128] = { id = 64128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Alle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich bei Leonidas Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung hat ihre Position in den Pestländern gefestigt und benötigt Eure Hilfe, um ihre Siege zu konsolidieren.\n\nSprecht mit Tal, unserem Windreitermeister, um nach Orgrimmar zu fliegen. Von dort bringt Euch Zeppelinmeister Frezza vor dem Haupttor zur Unterstadt. Ihr könnt von dort aus in die Östlichen Pestländer gelangen.\n\nDas Schicksal wartet!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64139] = { id = 64139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vorladung von Lady Liadrin", description = "Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lady Liadrin Eure Gegenwart.\n\nDas ist eine seltene Ehre, {name}. Normalerweise überlässt Lady Liadrin mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint sie ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, {name}.", sourceObjective = "Sprecht mit Lady Liadrin in Silbermond.", completion = "Wir werden den Grund Eures Besuchs noch früh genug besprechen. Doch zunächst muss ich feststellen, dass mich Eure bisherigen Leistungen und Euer Geschick in der Beherrschung des Lichts sehr beeindruckt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64140] = { id = 64140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Meisters", description = "Innerhalb unseres Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.\n\nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.\n\nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.", sourceObjective = "Sprecht erneut mit Lady Liadrin, um ihr Angebot, für Euch zu sprechen, anzunehmen.", completion = "Dass Ihr Euch entschlossen habt, mein Angebot zu akzeptieren, spricht für Euch, {name}. Ich wünsche Euch viel Glück, bei den von mir festzulegenden Prüfungen, doch bin ich zuversichtlich, dass Ihr sie alle meistern werdet.\n\nIch werde Euch die Aufgaben in der Reihenfolge ihrer Schwierigkeit, von der Leichtesten bis zur Schwersten, erteilen. Wir können beginnen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[64141] = { id = 64141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geste der Hingabe", description = "Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, {name}. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.\n\nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.", sourceObjective = "Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lady Liadrin in Silbermond.", progress = "Habt Ihr die von Magister Astalor benötigten Materialien bei Euch?", completion = "Hervorragend. Es sieht so aus, als sei alles da.\n\nKeine Sorge, im Laufe Eurer nächsten Aufgabe habt Ihr noch oft genug die Möglichkeit, von Eurer Waffe Gebrauch zu machen, versprochen!\n\nIch werde einen Initianden losschicken, um alles zu Magister Astalor zu bringen. Es wäre Verschwendung, Euch mit einem solch trivialen Botengang zu betrauen, wenn wesentlich wichtigere Dinge auf ihre Erledigung warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64142] = { id = 64142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration Eurer Loyalität", description = "Wir Blutritter haben geschworen, Quel'Thalas zu verteidigen, {name}. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.\n\nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.", sourceObjective = "Lady Liadrin in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.", progress = "Willkommen zurück, {name}. Habt Ihr die Geißel und ihre Fleischwagen zurückgeschlagen?", completion = "Ihr habt Loyalität gegenüber Eurer Heimat und Eure Aufopferungsbereitschaft für die Ziele des Ordens bewiesen, {name}.  Ich habe noch eine letzte Aufgabe für Euch, bevor Ihr den Titel eines Meisters für Euch beanspruchen dürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[64143] = { id = 64143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten das Licht auf eine Art zu nutzen und zu formen, wie es die sogenannten anderen 'Paladine' nie verstehen werden. Das hält sie jedoch nicht davon ab, uns dafür zu ächten, wie wir das wahre Potential des Lichts entfesseln.\n\nWir müssen ihnen klar machen, dass man mit Unseresgleichen keine Spielchen spielt. Was ich mir vorgestellt habe, ist keine schnelle Angelegenheit und auch nicht einfach, doch wenn Ihr Euch dieser Aufgabe verpflichtet, wird es Euer erstes Ziel sein, den Bibliotheksflügel der Abtei von Tyrs Hand zu infiltrieren und eine Phiole heiligen Wassers von Tyrs Hand an Euch zu bringen.", sourceObjective = "Bringt Lady Liadrin in Silbermond eine Phiole Weihwasser von Tyrs Hand.", progress = "Habt Ihr das Wasser bekommen?", completion = "Hmm... das ist eine recht kleine Menge, doch wenn wir vorsichtig vorgehen, sollte es ausreichen. Seht Ihr, der Scharlachrote Kreuzzug behauptet von sich noch immer, dem Licht zu dienen. Ich nehme an, dass sie das auch auf eine recht verdrehte Art und Weise noch immer tun, und genau diesen Umstand möchte ich ausnutzen.\n\nIhr fehlgeleiteter Eifer hat selbst den Segen dieses Wassers korrumpiert und das macht es ideal für meine Zwecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[64144] = { id = 64144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Jetzt, da wir das Wasser haben, benötigen wir eine Reihe von Zutaten in genau abgestimmten Mengen. Einige dieser Substanzen sind äußerst selten und wertvoll, {name}, doch ich habe Quellen für zwei von ihnen ausfindig gemacht.\n\n Ihr solltet einige arkane Katalysatoren bei Zalle, dem Reagenzienverkäufer in einem der Geschäfte auf dem Platz nahe der Todesschneise, bekommen. Darlia, die Giftlieferantin nahe der Schurkenausbilder in der Mördergasse, sollte über einen Vorrat an krepuskularem Pulver verfügen.\n\nUm meine Mixtur zu vervollständigen, benötige ich außerdem noch einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.", sourceObjective = "Bringt Lady Liadrin in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten.", progress = "Habt Ihr die von mir benötigten Zutaten bekommen?", completion = "Jetzt, wo wir über alle Zutaten verfügen, kann ich die Mixtur vorbereiten.\n\n<Ein Lächeln breitet sich langsam über Lady Liadrins Gesicht aus.>\n\nAlles entwickelt sich perfekt, {name}. Sobald ich hier fertig bin, werde ich Euch unseren letzten Schritt ausführlich erläutern.", sourceObjectiveStatus = "unverified-source-field" }
quests[64217] = { id = 64217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAlle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich in den Verwüsteten Landen zu melden. Begebt Euch zum Zeppelinmeister vor den Toren Orgrimmars und fliegt zum Basislager Grom'gol. Sprecht dort mit Thysta, um einen Flug nach Steinard zu erhalten.\n\nMeldet Euch umgehend bei Kriegsherr Dar'toon. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Kriegsherr Dar'toon ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64319] = { id = 64319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Studie der Macht", description = "Haltet mich nicht für übermäßig grausam, {name}. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.\n\nMeine Worte sind nicht als Grabesrede gedacht, {name}. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.\n\nEure Ausbildung in der Verwendung des Lichts hat sich bisher auf einfache Zauber und Tricks beschränkt. Es wird Zeit, dass Ihr die wahre Natur und Tiefe unserer Macht kennen lernt. Sucht Magister Astalor Blutschwur auf.", sourceObjective = "Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.", completion = "Willkommen junger {class}.\n\nBlutritter beziehen ihre Kraft von einem Wesen immenser Macht.\n\n\n\nIst es nicht glorreich? Es war ein Geschenk von unserem geliebten Prinz Kael'thas und ist die Grundlage der Macht der Blutritter über das Licht. Diese Kreatur möchte uns diese Macht vorenthalten, also haben wir eine Methode erfunden, sie ihr zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64845] = { id = 64845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitungen der Allianz", description = "Ein Krieg steht uns bevor und die Allianz braucht mehr Kämpfer, um die Horde zu besiegen!\n\nUnsere Mission lautet, ihre Einsätze auf allen Schlachtfeldern zu vereiteln.\n\nIhr wollt Euch den Soldaten anschließen, oder?", sourceObjective = "Gewinnt eine Schlacht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", progress = "Wie ist die Lage, {name}? Gibt es Neuigkeiten von der Front?", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65221] = { id = 65221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1 instabiles Fläschchen des Zauberhexers für 10 Apexissplitter erwerben", sourceObjective = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", sourceObjectiveStatus = "unverified-source-field" }
quests[65223] = { id = 65223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1 instabiles Fläschchen der Bestie für 10 Apexissplitter erwerben" }
quests[65284] = { id = 65284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Gumbokessel", sourceObjective = "Grüße, {class}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Booty Bay abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65285] = { id = 65285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Gumbokessel", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[65561] = { id = 65561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Flamme" }
quests[65562] = { id = 65562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Flamme" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen der Liebenden", description = "Ein Inkubus wird von den Herzen Liebender angelockt. Die sehnlichste Liebe erschafft einen unwiderstehlichen Köder.\n\nMeine Wahrsagung hat mir zwei Personen gezeigt, die ganz besonders geeignet sein sollten.\n\nIm Silberwald bietet Avelina Lilly den gefallenen Magiern von Mühlenbern ihre Dienste als Schneiderin an. Im Brachland hofft Isaac Pearson, sich im Küstendorf Ratschet einen Namen zu machen.\n\nSie arbeiten an entgegengesetzten Enden der Welt, doch ihre Herzen sehnen sich nur nach einander. Bringt ihre Herzen zu Carendin.", sourceObjective = "Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten.", progress = "Ah, {name}, Ihr seid zurückgekehrt. Konntet Ihr die Herzen der Liebenden beschaffen?", completion = "Hervorragend gemacht, wie erwartet, {name}.\n\n\n\nTrottel.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Endlich ist es so weit. Bringt die Herzen zum Beschwörungskreis dort unten. Legt sie in die Mitte und ruft den Inkubus herbei.\n\nDer Dämon wird wenig erfreut sein, wenn er merkt, dass Ihr ihn in eine Falle gelockt habt. Lasst Euch nicht von ihm bezaubern, {name}. Ihr müsst ihn vollständig unterwerfen.\n\nErst dann kann ich Euch den Zauber lehren, mit dem Ihr ihn an Euren Willen bindet.", sourceObjective = "Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Unterstadt zurück.", progress = "Der Inkubus beherrscht durchaus Kampfkünste, doch seine stärkste Waffe ist sein täuschender Charme. Ein Augenblick der Schwäche reicht, um von diesem Dämon betört zu werden.\n\nLasst das nicht zu, {name}.", completion = "Beeindruckend. Wirklich beeindruckend. Die Sayaad sind darauf spezialisiert, Sterbliche zu ihren Opfern zu machen. Viele Hexenmeister, die sich stark genug wähnten, um einen zu beherrschen, wurden stattdessen beherrscht.\n\nIhr habt der Prüfung standgehalten, {name}, und Euch Eure Belohnung verdient. Ich werde Euch den Zauber zur Beschwörung eines Inkubus lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe kann schmerzhaft sein", description = "Einen männlichen Sayaad nennt man einen Inkubus. Eine äußerst boshafte Kreatur, die nur eines im Sinn hat.\n\nDer Dämon muss mit einem Köder in unsere Welt gelockt werden, mit einem Gegenstand, der starke Liebe und Hingabe verkörpert.\n\nWenn Ihr Euch von einem Blinden führen lassen möchtet, {name}, dann hört zu. Östlich von der Kluft der Schatten, in der Gasse von Orgrimmar, lebt Magar. Er wartet darauf, dass sein Lebensgefährte Krilge zurückkehrt.\n\nGeht zu ihm. Er wird Euch bitten, etwas Wertvolles zu suchen. Dies wird der Schlüssel sein, den Ihr dann Gan'rul bringen müsst.", sourceObjective = "Sprecht mit Magar in Orgrimmar.", completion = "Wer hat Euch von Krilge erzählt? Habt Ihr Neuigkeiten? Ihr treibt hoffentlich keine Spielchen mit mir...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles aus Liebe", description = "Ihr werdet ein mächtiges Reagenz brauchen, um einen Inkubus anzulocken. Ein Objekt, das große Hingabe und Liebe verkörpert.\n\nDurch Wahrsagung habe ich eine kleine Statuette ausfindig gemacht, die für Euer Ritual geeignet sein sollte.\n\nVor Jahrtausenden gehörte die Figur einem jungen Paar. Die ursprünglichen Eigentümer sind verstorben, doch dieses Andenken besteht bis heute.\n\nFolgt der Straße nach Norden in das Eschental, dann Richtung Westen und an Maestras Posten vorbei. Ihr werdet ein Haus zwischen den Bäumen sehen. Dort findet Ihr, was Ihr sucht.", sourceObjective = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", progress = "Ihr seid zurück. Darf ich davon ausgehen, dass Ihr Erfolg hattet?", completion = "<Gakin dreht und wendet die Holzstatuette in seiner Hand.>\n\nIch kann die Energie der Emotionen in diesem Artefakt spüren. Die Zeit konnte ihm nichts anhaben. Es wird den Inkubus anlocken wie eine Blüte die Biene.\n\nAuf Takar kann man sich verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Es ist so weit. Nehmt die Statuette und steigt in die Gruft hinab. Ein Beschwörungskreis ist bereits vorbereitet. Ihr müsst die Statuette in der Mitte platzieren.\n\nDann wird sich das Tor öffnen und der Inkubus wird in unsere Welt kommen.\n\nIhr dürft einen Sayaad nicht unterschätzen. Der Dämon wird Euch angreifen, sobald er Eure Täuschung bemerkt. Ihr müsst alles einsetzen, was Ihr gelernt habt, um ihn zu besiegen.\n\nWenn Ihr Erfolg habt, kehrt zu mir zurück und ich unterwerfe die Kreatur Eurem Willen. Wenn Ihr versagt, ist Eure Seele verwirkt.", sourceObjective = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", progress = "Der Inkubus wird versuchen, Euch zu betören, zu täuschen und so zu überrumpeln. Der Dämon weiß genau, wie er die Herzen Sterblicher für sich gewinnt.\n\nDenkt daran, dass alle seine Versprechen Lügen sind. Für diesen Dämon seid Ihr nichts als Beute.", completion = "Nicht übel, {name}. Ihr habt das Scheusal bezwungen und Euer Wille blieb ungebrochen.\n\nManch ein Hexenmeister hielt sich schon für stark genug, einen Sayaad an sich zu binden, und endete stattdessen als nächste Mahlzeit des Dämons. Es freut mich, dass Ihr nicht so töricht seid.\n\nSeht genau zu, dann lehre ich Euch die Anrufung, mit der Ihr Euren jetzt unterworfenen Inkubus beschwört.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ja... verstehe. Ich kann die verbleibenden Emotionen spüren, die in diesem Stoff enthalten sind. Er ist mit Liebe verwoben. Dem wird der Inkubus nicht widerstehen können.\n\nBringt dies zum Beschwörungskreis in Neerus Zelt, {name}. Beschwört einen boshaften Inkubus und zeigt ihm, dass Ihr Eure Fähigkeiten gemeistert habt. Rechnet damit, dass er sich nicht still und leise unterwerfen lässt. Haltet Eure Magie bereit und macht Euch auf einen Kampf gefasst. Schon so mancher Hexenmeister hat seinen letzten Fehler begangen, indem er einen Dämon unterschätzt hat.\n\nBringt den Stoff zu mir zurück, sobald Ihr ihn bezwungen habt. Ich werde Magar sagen, was Ihr herausgefunden habt.", sourceObjective = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Blutauge in Orgrimmar zurück.", progress = "Die Sayaad unterwerfen den Verstand und quälen Seelen. Ihr Antlitz erfreut das Herz, sodass Ihr wehrlos seid, wenn sie mit Peitschen und Klauen in Euer Fleisch reißen.\n\nLasst Euch vom Inkubus nicht betören, {name}. Tötet ihn schnell und bringt es zu Ende.", completion = "Ha! Siegreich, wie ich es erwartet hatte!\n\nDer Inkubus wurde bezwungen, und ich werde Euch mit Freuden lehren, wie man den Dämon beschwört. Ihr werdet stärker und steht zweifelsohne davor, noch größere Macht zu erschließen.\n\nIch werde Magar den Schal zurückbringen. Ich kenne diesen Orc schon seit vielen Jahren und hätte nie gedacht, dass ihm einmal jemand so wie Krilge am Herzen liegen würde.\n\nDas erinnert uns daran, was uns von den Dämonen unterscheidet. Wir nutzen ihre Dunkelheit, lassen uns aber niemals von ihnen nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwo anders", description = "Ich habe Krilge bei der Herstellung von Mondstoff im Eschental kennengelernt. Er war dort stationiert, um Zivilisten vor Gefahren zu beschützen, bis er dann verschwand...\n\nSie haben die Suche aufgegeben und sehen ihn als Deserteur, aber das glaube ich nicht.\n\nWir haben uns oft am Himmelssturzsee getroffen, bevor der von diesen aggressiven Sumpfmonstern überrannt wurde.\n\nIch bitte nur ungern andere um Gefallen, aber wenn Ihr ins Eschental gehen und nach ihm Ausschau halten könntet, wäre ich Euch dankbar.", sourceObjective = "Untersucht den Himmelssturzsee im Eschental und erstattet Gan'rul Blutauge in Orgrimmar Bericht.", progress = "Ja, was gibt's?", completion = "Was habt Ihr da, {name}? Einen Schal aus... Mondstoff? Ihr wollt mich doch hoffentlich nicht bezirzen.", sourceObjectiveStatus = "unverified-source-field" }
